(function() {
    'use strict';

    class MicrofinanceAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Microfinance Impact: Financial Inclusion';
            this.version = '1.1.0';
            this.GNI_PER_CAPITA = 6000;
            this.ROUNDS = [
                {
                    titleKey: 'r1_title',
                    briefingKey: 'r1_briefing',
                    d1LabelKey: 'r1_d1_label',
                    d1HintKey: 'r1_d1_hint',
                    d1Min: 0,
                    d1Max: 50,
                    d1Default: 15,
                    d1Unit: '%',
                    d2LabelKey: 'r1_d2_label',
                    d2HintKey: 'r1_d2_hint',
                    d2Min: 0,
                    d2Max: 100,
                    d2Default: 50,
                    d2Unit: '%'
                },
                {
                    titleKey: 'r2_title',
                    briefingKey: 'r2_briefing',
                    d1LabelKey: 'r2_d1_label',
                    d1HintKey: 'r2_d1_hint',
                    d1Min: 0,
                    d1Max: 100,
                    d1Default: 60,
                    d1Unit: '%',
                    d2LabelKey: 'r2_d2_label',
                    d2HintKey: 'r2_d2_hint',
                    d2Min: 0,
                    d2Max: 100,
                    d2Default: 40,
                    d2Unit: '%'
                },
                {
                    titleKey: 'r3_title',
                    briefingKey: 'r3_briefing',
                    d1LabelKey: 'r3_d1_label',
                    d1HintKey: 'r3_d1_hint',
                    d1Min: 18,
                    d1Max: 45,
                    d1Default: 30,
                    d1Unit: '%',
                    d2LabelKey: 'r3_d2_label',
                    d2HintKey: 'r3_d2_hint',
                    d2Min: 0,
                    d2Max: 50,
                    d2Default: 20,
                    d2Unit: '%'
                },
                {
                    titleKey: 'r4_title',
                    briefingKey: 'r4_briefing',
                    d1LabelKey: 'r4_d1_label',
                    d1HintKey: 'r4_d1_hint',
                    d1Min: 0,
                    d1Max: 100,
                    d1Default: 50,
                    d1Unit: '%',
                    d2LabelKey: 'r4_d2_label',
                    d2HintKey: 'r4_d2_hint',
                    d2Min: 0,
                    d2Max: 100,
                    d2Default: 40,
                    d2Unit: '%'
                },
                {
                    titleKey: 'r5_title',
                    briefingKey: 'r5_briefing',
                    d1LabelKey: 'r5_d1_label',
                    d1HintKey: 'r5_d1_hint',
                    d1Min: 0,
                    d1Max: 100,
                    d1Default: 50,
                    d1Unit: '%',
                    d2LabelKey: 'r5_d2_label',
                    d2HintKey: 'r5_d2_hint',
                    d2Min: 0,
                    d2Max: 100,
                    d2Default: 50,
                    d2Unit: '%'
                },
                {
                    titleKey: 'r6_title',
                    briefingKey: 'r6_briefing',
                    d1LabelKey: 'r6_d1_label',
                    d1HintKey: 'r6_d1_hint',
                    d1Min: 0,
                    d1Max: 100,
                    d1Default: 70,
                    d1Unit: '%',
                    d2LabelKey: 'r6_d2_label',
                    d2HintKey: 'r6_d2_hint',
                    d2Min: 0,
                    d2Max: 100,
                    d2Default: 50,
                    d2Unit: '%'
                }
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 1500000,
                    grossPortfolio: 8200000,
                    activeBorrowers: 14800,
                    womenPct: 78,
                    ruralPct: 65,
                    par30: 7.8,
                    oss: 94,
                    costPerBorrower: 187,
                    avgLoanSize: 554,
                    interestRate: 32,
                    depth: 9.2,
                    equity: 2050000,
                    donorFunding: 2870000,
                    commercialDebt: 3280000,
                    investorConfidence: 50,
                    donorConfidence: 70,
                    regulatorConfidence: 60,
                    ossHistory: [],
                    parHistory: [],
                    borrowerHistory: [],
                    socialScoreHistory: [],
                    financialScoreHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    decision1: 25,
                    decision2: 50
                };
            }
            this._setupSliderListeners();
            this._updateBriefing(state);
        }

        _setupSliderListeners() {
            var slider1 = document.getElementById('decision1Input');
            var display1 = document.getElementById('decision1Value');
            if (slider1 && display1) {
                slider1.addEventListener('input', function() {
                    display1.textContent = slider1.value;
                });
            }
            var slider2 = document.getElementById('decision2Input');
            var display2 = document.getElementById('decision2Value');
            if (slider2 && display2) {
                slider2.addEventListener('input', function() {
                    display2.textContent = slider2.value;
                });
            }
        }

        _updateBriefing(state) {
            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];
            var t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : function(k) { return k; };

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(round.briefingKey);

            var d1Label = document.getElementById('decision1Label');
            if (d1Label) d1Label.textContent = t(round.d1LabelKey);

            var d1Hint = document.getElementById('decision1Hint');
            if (d1Hint) d1Hint.textContent = t(round.d1HintKey);

            var d1Min = document.getElementById('decision1Min');
            if (d1Min) d1Min.textContent = round.d1Min + round.d1Unit;

            var d1Max = document.getElementById('decision1Max');
            if (d1Max) d1Max.textContent = round.d1Max + round.d1Unit;

            var slider1 = document.getElementById('decision1Input');
            if (slider1) {
                slider1.min = round.d1Min;
                slider1.max = round.d1Max;
                slider1.value = round.d1Default;
            }
            var d1Val = document.getElementById('decision1Value');
            if (d1Val) d1Val.textContent = round.d1Default;

            var d2Label = document.getElementById('decision2Label');
            if (d2Label) d2Label.textContent = t(round.d2LabelKey);

            var d2Hint = document.getElementById('decision2Hint');
            if (d2Hint) d2Hint.textContent = t(round.d2HintKey);

            var d2Min = document.getElementById('decision2Min');
            if (d2Min) d2Min.textContent = round.d2Min + round.d2Unit;

            var d2Max = document.getElementById('decision2Max');
            if (d2Max) d2Max.textContent = round.d2Max + round.d2Unit;

            var slider2 = document.getElementById('decision2Input');
            if (slider2) {
                slider2.min = round.d2Min;
                slider2.max = round.d2Max;
                slider2.value = round.d2Default;
            }
            var d2Val = document.getElementById('decision2Value');
            if (d2Val) d2Val.textContent = round.d2Default;

            this._updateStakeholderBars(state);
        }

        _updateStakeholderBars(state) {
            var ds = state.domainState;
            if (!ds) return;

            var invBar = document.getElementById('investorBar');
            if (invBar) invBar.style.width = Math.max(0, Math.min(100, ds.investorConfidence)) + '%';

            var donBar = document.getElementById('donorBar');
            if (donBar) donBar.style.width = Math.max(0, Math.min(100, ds.donorConfidence)) + '%';

            var regBar = document.getElementById('regulatorBar');
            if (regBar) regBar.style.width = Math.max(0, Math.min(100, ds.regulatorConfidence)) + '%';
        }

        validateDecisions(decisions) {
            var slider1 = document.getElementById('decision1Input');
            if (slider1) decisions.decision1 = parseFloat(slider1.value);

            var slider2 = document.getElementById('decision2Input');
            if (slider2) decisions.decision2 = parseFloat(slider2.value);

            this._updateBriefing(window.mySimulation.state);

            if (isNaN(decisions.decision1) || isNaN(decisions.decision2)) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('invalid_input'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) {
            var d1 = state.decisions.decision1;
            var d2 = state.decisions.decision2;
            var ds = state.domainState;
            var period = state.currentPeriod;
            var results = {};

            if (period === 1) {
                results = this._calcRound1(ds, d1, d2);
            } else if (period === 2) {
                results = this._calcRound2(ds, d1, d2);
            } else if (period === 3) {
                results = this._calcRound3(ds, d1, d2);
            } else if (period === 4) {
                results = this._calcRound4(ds, d1, d2);
            } else if (period === 5) {
                results = this._calcRound5(ds, d1, d2);
            } else if (period === 6) {
                results = this._calcRound6(ds, d1, d2);
            }

            ds.depth = Math.round(ds.avgLoanSize / this.GNI_PER_CAPITA * 1000) / 10;

            var opRevenue = ds.grossPortfolio * ds.interestRate / 100;
            var finExpense = ds.commercialDebt * 0.08 + ds.donorFunding * 0.02;
            var loanLossProv = ds.grossPortfolio * ds.par30 / 100 * 0.5;
            var opExpense = ds.activeBorrowers * ds.costPerBorrower;
            var totalExpense = finExpense + loanLossProv + opExpense;
            ds.oss = totalExpense > 0 ? Math.round(opRevenue / totalExpense * 100) : 0;

            ds.ossHistory.push(ds.oss);
            ds.parHistory.push(Math.round(ds.par30 * 10) / 10);
            ds.borrowerHistory.push(ds.activeBorrowers);

            var socialScore = Math.round(
                (ds.womenPct / 100 * 25) +
                (Math.min(ds.activeBorrowers / 25000, 1) * 25) +
                (Math.max(0, 1 - ds.depth / 50) * 25) +
                (ds.ruralPct / 100 * 25)
            );
            ds.socialScoreHistory.push(socialScore);

            var financialScore = Math.round(
                (Math.min(ds.oss / 150, 1) * 40) +
                (Math.max(0, 1 - ds.par30 / 15) * 35) +
                (Math.min(ds.cash / 3000000, 1) * 25)
            );
            ds.financialScoreHistory.push(financialScore);

            results.period = period;
            results.oss = ds.oss;
            results.par30 = Math.round(ds.par30 * 10) / 10;
            results.borrowers = ds.activeBorrowers;
            results.portfolio = ds.grossPortfolio;
            results.socialScore = socialScore;
            results.financialScore = financialScore;
            results.investorConf = ds.investorConfidence;
            results.donorConf = ds.donorConfidence;
            results.regulatorConf = ds.regulatorConfidence;

            var self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1, domainState: ds });
                self._updateStakeholderBars({ domainState: ds });
            }, 500);

            return results;
        }

        _calcRound1(ds, writeOffPct, collectionEffort) {
            var parPortionWritten = ds.grossPortfolio * ds.par30 / 100 * writeOffPct / 100;
            ds.grossPortfolio -= parPortionWritten;
            ds.cash -= parPortionWritten * 0.3;
            ds.par30 = Math.max(1, ds.par30 - (writeOffPct * 0.12) - (collectionEffort * 0.025));
            ds.par30 = Math.round(ds.par30 * 10) / 10;

            var collectionCost = ds.activeBorrowers * ds.costPerBorrower * collectionEffort / 100 * 0.15;
            ds.cash -= collectionCost;

            if (writeOffPct > 25) {
                ds.investorConfidence += 8;
                ds.donorConfidence -= 5;
                ds.regulatorConfidence += 5;
            } else {
                ds.investorConfidence -= 3;
                ds.donorConfidence += 3;
            }

            if (collectionEffort > 70) {
                ds.donorConfidence -= 4;
            }

            ds.investorConfidence = Math.max(0, Math.min(100, ds.investorConfidence));
            ds.donorConfidence = Math.max(0, Math.min(100, ds.donorConfidence));
            ds.regulatorConfidence = Math.max(0, Math.min(100, ds.regulatorConfidence));

            return {
                writeOffAmount: Math.round(parPortionWritten),
                collectionCost: Math.round(collectionCost),
                newPar30: ds.par30
            };
        }

        _calcRound2(ds, groupLendingPct, urbanExpansionPct) {
            var growthRate = 0.08 + (urbanExpansionPct / 100 * 0.07);
            var newBorrowers = Math.round(ds.activeBorrowers * growthRate);
            ds.activeBorrowers += newBorrowers;

            var groupNewAvg = 350;
            var individualNewAvg = 1200;
            var weightedNewAvgLoan = groupLendingPct / 100 * groupNewAvg + (1 - groupLendingPct / 100) * individualNewAvg;
            var newPortionSize = newBorrowers * weightedNewAvgLoan;
            ds.grossPortfolio += newPortionSize;
            ds.avgLoanSize = Math.round(ds.grossPortfolio / ds.activeBorrowers);

            var groupWomenRate = 85;
            var urbanWomenRate = 55;
            var newWomenRate = groupLendingPct / 100 * groupWomenRate + (1 - groupLendingPct / 100) * urbanWomenRate;
            var totalWomen = ds.womenPct / 100 * (ds.activeBorrowers - newBorrowers) + newWomenRate / 100 * newBorrowers;
            ds.womenPct = Math.round(totalWomen / ds.activeBorrowers * 1000) / 10;

            var groupCost = 140;
            var urbanCost = 220;
            var newAvgCost = groupLendingPct / 100 * groupCost + (1 - groupLendingPct / 100) * urbanCost;
            ds.costPerBorrower = Math.round((ds.costPerBorrower * 0.7 + newAvgCost * 0.3));

            ds.ruralPct = Math.round(ds.ruralPct * (1 - urbanExpansionPct / 100 * 0.15));

            if (groupLendingPct > 60) {
                ds.donorConfidence += 6;
                ds.investorConfidence -= 3;
            } else {
                ds.donorConfidence -= 4;
                ds.investorConfidence += 5;
            }
            if (urbanExpansionPct > 60) {
                ds.investorConfidence += 4;
                ds.donorConfidence -= 5;
            }

            ds.investorConfidence = Math.max(0, Math.min(100, ds.investorConfidence));
            ds.donorConfidence = Math.max(0, Math.min(100, ds.donorConfidence));

            return {
                newBorrowers: newBorrowers,
                newPortfolioGrowth: Math.round(newPortionSize),
                avgLoanSize: ds.avgLoanSize,
                womenPct: ds.womenPct
            };
        }

        _calcRound3(ds, interestRate, costReductionInvest) {
            var prevRate = ds.interestRate;
            ds.interestRate = interestRate;

            var reductionCost = ds.activeBorrowers * ds.costPerBorrower * costReductionInvest / 100 * 0.25;
            ds.cash -= reductionCost;
            ds.costPerBorrower = Math.round(ds.costPerBorrower * (1 - costReductionInvest / 100 * 0.12));

            var rateIsLegal = interestRate <= 28;

            if (rateIsLegal) {
                ds.regulatorConfidence += 10;
            } else if (interestRate <= 35) {
                ds.regulatorConfidence -= 5;
            } else {
                ds.regulatorConfidence -= 15;
                ds.donorConfidence -= 8;
            }

            if (interestRate < 25) {
                ds.donorConfidence += 8;
                ds.investorConfidence -= 10;
            } else if (interestRate > 35) {
                ds.donorConfidence -= 10;
                ds.investorConfidence += 8;
            }

            var revenue = ds.grossPortfolio * interestRate / 100;
            var minSustainableRate = (ds.activeBorrowers * ds.costPerBorrower + ds.grossPortfolio * ds.par30 / 100 * 0.5 + ds.commercialDebt * 0.08) / ds.grossPortfolio * 100;
            var surplus = revenue - ds.grossPortfolio * minSustainableRate / 100;
            ds.cash += surplus * 0.4;

            ds.investorConfidence = Math.max(0, Math.min(100, ds.investorConfidence));
            ds.donorConfidence = Math.max(0, Math.min(100, ds.donorConfidence));
            ds.regulatorConfidence = Math.max(0, Math.min(100, ds.regulatorConfidence));

            return {
                interestRate: interestRate,
                rateIsLegal: rateIsLegal,
                minSustainableRate: Math.round(minSustainableRate * 10) / 10,
                reductionCost: Math.round(reductionCost),
                costPerBorrower: ds.costPerBorrower,
                surplus: Math.round(surplus)
            };
        }

        _calcRound4(ds, equityAcceptPct, regulatoryPursuit) {
            var equityAmount = 5000000 * equityAcceptPct / 100;
            ds.equity += equityAmount;
            ds.cash += equityAmount;

            var licenseCost = ds.cash * regulatoryPursuit / 100 * 0.08;
            ds.cash -= licenseCost;

            var hasLicense = regulatoryPursuit > 60;
            if (hasLicense) {
                var depositMobilization = ds.activeBorrowers * 0.4 * 200;
                ds.cash += depositMobilization;
                ds.donorFunding *= 0.7;
            }

            if (equityAcceptPct > 60) {
                ds.investorConfidence += 12;
                ds.donorConfidence -= 8;
            } else if (equityAcceptPct < 20) {
                ds.investorConfidence -= 10;
                ds.donorConfidence += 5;
            }

            if (regulatoryPursuit > 60) {
                ds.regulatorConfidence += 10;
                ds.investorConfidence += 5;
            }

            ds.investorConfidence = Math.max(0, Math.min(100, ds.investorConfidence));
            ds.donorConfidence = Math.max(0, Math.min(100, ds.donorConfidence));
            ds.regulatorConfidence = Math.max(0, Math.min(100, ds.regulatorConfidence));

            return {
                equityAccepted: Math.round(equityAmount),
                licenseCost: Math.round(licenseCost),
                hasLicense: hasLicense,
                depositMobilization: hasLicense ? Math.round(ds.activeBorrowers * 0.4 * 200) : 0
            };
        }

        _calcRound5(ds, clientRelief, stakeholderComms) {
            var crisisTypes = [
                { name: 'El Nino drought', parShock: 8, portfolioHit: 0.06 },
                { name: 'Currency devaluation 18%', parShock: 5, portfolioHit: 0.04 },
                { name: 'Fintech competitor launch', parShock: 3, portfolioHit: 0.02 },
                { name: 'Earthquake in key region', parShock: 10, portfolioHit: 0.08 }
            ];
            var crisisIdx = (ds.activeBorrowers + ds.grossPortfolio) % crisisTypes.length;
            var crisis = crisisTypes[crisisIdx];

            ds.par30 += crisis.parShock;
            ds.grossPortfolio -= ds.grossPortfolio * crisis.portfolioHit;

            var reliefCost = ds.cash * clientRelief / 100 * 0.2;
            ds.cash -= reliefCost;
            ds.par30 -= clientRelief / 100 * crisis.parShock * 0.5;
            ds.par30 = Math.max(2, Math.round(ds.par30 * 10) / 10);

            var commsCost = ds.cash * stakeholderComms / 100 * 0.05;
            ds.cash -= commsCost;

            if (clientRelief > 60) {
                ds.donorConfidence += 10;
                ds.investorConfidence -= 5;
                ds.activeBorrowers = Math.round(ds.activeBorrowers * 0.97);
            } else {
                ds.donorConfidence -= 8;
                ds.investorConfidence += 3;
                ds.activeBorrowers = Math.round(ds.activeBorrowers * 0.92);
            }

            if (stakeholderComms > 50) {
                ds.investorConfidence += 5;
                ds.donorConfidence += 3;
                ds.regulatorConfidence += 5;
            }

            ds.investorConfidence = Math.max(0, Math.min(100, ds.investorConfidence));
            ds.donorConfidence = Math.max(0, Math.min(100, ds.donorConfidence));
            ds.regulatorConfidence = Math.max(0, Math.min(100, ds.regulatorConfidence));

            return {
                crisisName: crisis.name,
                parShock: crisis.parShock,
                reliefCost: Math.round(reliefCost),
                commsCost: Math.round(commsCost),
                borrowerRetention: clientRelief > 60 ? 97 : 92
            };
        }

        _calcRound6(ds, transparencyLevel, socialEmphasis) {
            var honestGood = ds.oss > 110 && ds.par30 < 5;
            var honestBad = ds.oss < 100 || ds.par30 > 8;

            if (transparencyLevel > 70) {
                if (honestGood) {
                    ds.investorConfidence += 10;
                    ds.donorConfidence += 10;
                    ds.regulatorConfidence += 10;
                } else if (honestBad) {
                    ds.investorConfidence -= 5;
                    ds.donorConfidence += 8;
                    ds.regulatorConfidence += 8;
                } else {
                    ds.investorConfidence += 3;
                    ds.donorConfidence += 6;
                    ds.regulatorConfidence += 6;
                }
            } else {
                ds.investorConfidence += 2;
                ds.donorConfidence -= 5;
                ds.regulatorConfidence -= 5;
            }

            if (socialEmphasis > 60) {
                ds.donorConfidence += 8;
                ds.investorConfidence -= 4;
            } else {
                ds.donorConfidence -= 4;
                ds.investorConfidence += 6;
            }

            ds.investorConfidence = Math.max(0, Math.min(100, ds.investorConfidence));
            ds.donorConfidence = Math.max(0, Math.min(100, ds.donorConfidence));
            ds.regulatorConfidence = Math.max(0, Math.min(100, ds.regulatorConfidence));

            return {
                transparencyLevel: transparencyLevel,
                socialEmphasis: socialEmphasis,
                finalOSS: ds.oss,
                finalPAR: ds.par30,
                finalBorrowers: ds.activeBorrowers,
                finalWomenPct: ds.womenPct,
                finalDepth: ds.depth
            };
        }

